Language: Java (object-oriented paradigm)

## Task specification given to the author
- Implement `createGraph`: Create a directed weighted graph with the given number of vertices (0-indexed).
- Implement `addEdge`: Add a directed edge from vertex `from` to vertex `to` with the given non-negative weight. Support multiple edges between the same pair.
- Implement `dijkstra`: Run Dijkstra's algorithm from the given source vertex. Return a PathResult with shortest distances and predecessor array. Unreachable vertices must have distance Double.POSITIVE_INFINITY. Return null if graph is null or source out of bounds.
- Implement `getShortestDistance`: Return shortest distance to target. Return Double.POSITIVE_INFINITY if target out of bounds or result is null.
- Implement `reconstructPath`: Return int[] of vertex indices from source to target. Return null if unreachable, out of bounds, or result is null.
- Use a priority queue for O((V+E) log V) time complexity.
- Keep the contract in `ShortestPath.java`, the concrete solution in `ShortestPathImpl.java`.
- Return only raw Java code.

## Contract given to the author (ShortestPath.java, not written by the author)
```java
import java.util.List;
import java.util.ArrayList;

public abstract class ShortestPath {
    protected ShortestPath() {}

    public static final class Edge {
        public int to;
        public double weight;
        public Edge(int to, double weight) { this.to = to; this.weight = weight; }
    }

    public static final class Graph {
        public List<List<Edge>> adjacency;
        public int numVertices;
        public Graph(int numVertices) {
            this.numVertices = Math.max(numVertices, 0);
            this.adjacency = new ArrayList<>();
            for (int i = 0; i < this.numVertices; i++)
                this.adjacency.add(new ArrayList<>());
        }
    }

    public static final class PathResult {
        public double[] distances;
        public int[] predecessors;
        public int source;
        public PathResult(int numVertices, int source) {
            this.distances = new double[numVertices];
            this.predecessors = new int[numVertices];
            this.source = source;
        }
    }

    public abstract Graph createGraph(int numVertices);
    public abstract void addEdge(Graph graph, int from, int to, double weight);
    public abstract PathResult dijkstra(Graph graph, int source);
    public abstract double getShortestDistance(PathResult result, int target);
    public abstract int[] reconstructPath(PathResult result, int target);
}

```

## Code to evaluate (ShortestPathImpl.java)
```java
import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Deque;
import java.util.List;
import java.util.PriorityQueue;

public final class ShortestPathImpl extends ShortestPath {

    private static final class QueueEntry {
        private final int vertex;
        private final double distance;

        private QueueEntry(int vertex, double distance) {
            this.vertex = vertex;
            this.distance = distance;
        }
    }

    public ShortestPathImpl() {
        super();
    }

    @Override
    public Graph createGraph(int numVertices) {
        return new Graph(numVertices);
    }

    @Override
    public void addEdge(Graph graph, int from, int to, double weight) {
        if (graph == null) {
            throw new IllegalArgumentException("Graph must not be null");
        }
        if (from < 0 || from >= graph.numVertices) {
            throw new IllegalArgumentException("Invalid 'from' vertex: " + from);
        }
        if (to < 0 || to >= graph.numVertices) {
            throw new IllegalArgumentException("Invalid 'to' vertex: " + to);
        }
        if (Double.isNaN(weight) || weight < 0) {
            throw new IllegalArgumentException("Edge weight must be non-negative: " + weight);
        }
        graph.adjacency.get(from).add(new Edge(to, weight));
    }

    @Override
    public PathResult dijkstra(Graph graph, int source) {
        if (graph == null || source < 0 || source >= graph.numVertices) {
            return null;
        }

        int n = graph.numVertices;
        PathResult result = new PathResult(n, source);
        Arrays.fill(result.distances, Double.POSITIVE_INFINITY);
        Arrays.fill(result.predecessors, -1);
        result.distances[source] = 0.0;

        PriorityQueue<QueueEntry> queue = new PriorityQueue<>(
                (a, b) -> Double.compare(a.distance, b.distance));
        queue.offer(new QueueEntry(source, 0.0));

        while (!queue.isEmpty()) {
            QueueEntry current = queue.poll();
            int u = current.vertex;

            if (current.distance > result.distances[u]) {
                continue;
            }

            for (Edge edge : graph.adjacency.get(u)) {
                int v = edge.to;
                double candidate = result.distances[u] + edge.weight;
                if (candidate < result.distances[v]) {
                    result.distances[v] = candidate;
                    result.predecessors[v] = u;
                    queue.offer(new QueueEntry(v, candidate));
                }
            }
        }

        return result;
    }

    @Override
    public double getShortestDistance(PathResult result, int target) {
        if (result == null || result.distances == null
                || target < 0 || target >= result.distances.length) {
            return Double.POSITIVE_INFINITY;
        }
        return result.distances[target];
    }

    @Override
    public int[] reconstructPath(PathResult result, int target) {
        if (result == null || result.distances == null || result.predecessors == null
                || target < 0 || target >= result.distances.length
                || target >= result.predecessors.length) {
            return null;
        }
        if (Double.isInfinite(result.distances[target])) {
            return null;
        }

        Deque<Integer> path = new ArrayDeque<>();
        int current = target;
        int steps = 0;
        int limit = result.predecessors.length;

        while (current != -1) {
            if (steps++ > limit) {
                return null;
            }
            path.addFirst(current);
            if (current == result.source) {
                break;
            }
            current = result.predecessors[current];
        }

        if (path.isEmpty() || path.peekFirst() != result.source) {
            return null;
        }

        List<Integer> list = new ArrayList<>(path);
        int[] output = new int[list.size()];
        for (int i = 0; i < output.length; i++) {
            output[i] = list.get(i);
        }
        return output;
    }
}

